package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.InflaterInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen1Test {

    private byte[] createZipWithData(String content) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private byte[] createZipWithStoredEntry(String content) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("stored.txt");
            entry.setMethod(ZipEntry.STORED);
            entry.setSize(content.length());
            entry.setCrc(new CRC32().update(content.getBytes()) == 0 ? 0 : 0); // Dummy CRC logic for setup
            // Manual CRC calculation for STORED
            CRC32 crc = new CRC32();
            crc.update(content.getBytes());
            entry.setCrc(crc.getValue());

            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    @Test(expected = IOException.class)
    public void testRead_ClosedStream() throws IOException {
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(new byte[0]));
        zais.close();
        zais.read(new byte[10], 0, 10);
    }

    @Test
    public void testRead_FinishedOrNullEntry() throws IOException {
        byte[] data = createZipWithData("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        zais.close(); // Simulate finished

        int result = zais.read(new byte[10], 0, 10);
        Assert.assertEquals(-1, result);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferBounds() throws IOException {
        byte[] data = createZipWithData("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        // start > buffer.length
        zais.read(new byte[5], 10, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength() throws IOException {
        byte[] data = createZipWithData("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        zais.read(new byte[5], 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_BufferOverflow() throws IOException {
        byte[] data = createZipWithData("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        // buffer.length - start < length
        zais.read(new byte[5], 2, 4);
    }

    @Test
    public void testRead_DeflatedData() throws IOException {
        String content = "This is a test string for deflation";
        byte[] data = createZipWithData(content);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        int read = zais.read(buffer, 0, 10);
        Assert.assertEquals(10, read);
        Assert.assertEquals(content.substring(0, 10), new String(buffer, 0, 10));

        int read2 = zais.read(buffer, 0, 10);
        Assert.assertTrue(read2 > 0);
    }

    @Test
    public void testRead_StoredData() throws IOException {
        String content = "Stored content";
        byte[] data = createZipWithStoredEntry(content);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();

        byte[] buffer = new byte[5];
        // First read
        int read1 = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read1);
        Assert.assertEquals("Store", new String(buffer, 0, 5));

        // Second read (triggers offsetInBuffer logic)
        int read2 = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read2);
        Assert.assertEquals("d con", new String(buffer, 0, 5));

        // Third read (triggers lengthOfLastRead logic)
        int read3 = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read3);
        Assert.assertEquals("tent", new String(buffer, 0, 4)); // partial
    }

    @Test
    public void testRead_StoredData_EndOfStream() throws IOException {
        String content = "abc";
        byte[] data = createZipWithStoredEntry(content);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        int read = zais.read(buffer, 0, 10);
        Assert.assertEquals(3, read);

        int readEnd = zais.read(buffer, 0, 10);
        Assert.assertEquals(-1, readEnd);
    }

    @Test(expected = IOException.class)
    public void testRead_TruncatedZip() throws IOException {
        // To trigger "Truncated ZIP file", we need inf.inflate to return 0 
        // but inf.finished() to be false and lengthOfLastRead to be 0.
        // This is hard to simulate with standard ZipOutputStream, 
        // but we can approximate by feeding bad data.
        byte[] badData = new byte[]{ (byte)0x50, (byte)0x4B, 0x03, 0x04, 0x00, 0x00 }; 
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(badData));
        zais.getNextZipEntry();
        zais.read(new byte[10], 0, 10);
    }
}
